[CmdletBinding()]
param(
    [Parameter(Position = 0)]
    [string]$Command = 'help',

    [Parameter(Position = 1, ValueFromRemainingArguments)]
    [string[]]$CliArguments = @()
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
Import-Module (Join-Path $PSScriptRoot 'TaskForge.Core.psm1') -Force -WarningAction SilentlyContinue

try {
    $command = $Command.ToLowerInvariant()

    $cliArgs = @($CliArguments)
    $configAction = $null
    if ($command -eq 'config') {
        if ($cliArgs.Count -ge 1 -and -not $cliArgs[0].StartsWith('--')) {
            $configAction = $cliArgs[0].ToLowerInvariant()
            $cliArgs = @($cliArgs | Select-Object -Skip 1)
        }
    }

    $options = ConvertFrom-TaskForgeArguments -Arguments $cliArgs

    $defaultConfigFile = Join-Path (Split-Path -Parent $PSScriptRoot) 'config/taskforge.config.json'
    $configFile = if ($options.Contains('config-file')) {
        Get-RequiredOption -Options $options -Name 'config-file'
    }
    else {
        $defaultConfigFile
    }
    $config = Read-TaskForgeConfig -Path $configFile

    $defaultDataFile = Join-Path (Split-Path -Parent $PSScriptRoot) 'data/tasks.json'
    $dataFile = if ($options.Contains('data-file')) {
        Get-RequiredOption -Options $options -Name 'data-file'
    }
    elseif ($config.Contains('dataFile')) {
        Resolve-TaskForgeConfigPath -ConfigFile $configFile -Value $config['dataFile']
    }
    else {
        $defaultDataFile
    }
    $asJson = $options.Contains('json') -or ($config.Contains('defaultJson') -and $config['defaultJson'])

    switch ($command) {
        'add' {
            Assert-KnownOptions -Options $options -Allowed @('title', 'description', 'data-file', 'json', 'config-file')
            $title = Get-RequiredOption -Options $options -Name 'title'
            $tasks = @(Read-TaskStore -Path $dataFile)
            $nextId = if ($tasks.Count -eq 0) { 1 } else { 1 + [int](($tasks | Measure-Object -Property id -Maximum).Maximum) }
            $task = [ordered]@{
                id = $nextId
                title = $title.Trim()
                description = if ($options.Contains('description')) { [string]$options['description'] } else { '' }
                status = 'pending'
                createdAt = [DateTimeOffset]::UtcNow.ToString('o')
            }
            Write-TaskStore -Path $dataFile -Tasks @($tasks + [pscustomobject]$task)
            if ($asJson) {
                Write-TaskForgeOutput -Value ([pscustomobject]$task) -AsJson $true
            }
            else {
                "Added task ${nextId}: $($task.title)"
            }
        }
        'list' {
            Assert-KnownOptions -Options $options -Allowed @('data-file', 'json', 'config-file')
            $tasks = @(Read-TaskStore -Path $dataFile | Sort-Object { [int]$_.id })
            if ($asJson) {
                Write-TaskForgeOutput -Value $tasks -AsJson $true
            }
            elseif ($tasks.Count -eq 0) {
                'No tasks.'
            }
            else {
                $tasks | ForEach-Object { "[{0}] #{1} {2}" -f $_.status, $_.id, $_.title }
            }
        }
        'complete' {
            Assert-KnownOptions -Options $options -Allowed @('id', 'data-file', 'json', 'config-file')
            $idText = Get-RequiredOption -Options $options -Name 'id'
            $id = 0
            if (-not [int]::TryParse($idText, [ref]$id) -or $id -le 0) {
                throw '--id must be a positive integer.'
            }
            $tasks = @(Read-TaskStore -Path $dataFile)
            $task = $tasks | Where-Object { [int]$_.id -eq $id } | Select-Object -First 1
            if ($null -eq $task) {
                throw "Task $id was not found."
            }
            $task.status = 'completed'
            Write-TaskStore -Path $dataFile -Tasks $tasks
            if ($asJson) {
                Write-TaskForgeOutput -Value $task -AsJson $true
            }
            else {
                "Completed task $id."
            }
        }
        'remove' {
            Assert-KnownOptions -Options $options -Allowed @('id', 'data-file', 'json', 'config-file')
            $idText = Get-RequiredOption -Options $options -Name 'id'
            $id = 0
            if (-not [int]::TryParse($idText, [ref]$id) -or $id -le 0) {
                throw '--id must be a positive integer.'
            }
            $tasks = @(Read-TaskStore -Path $dataFile)
            $remaining = @($tasks | Where-Object { [int]$_.id -ne $id })
            if ($remaining.Count -eq $tasks.Count) {
                throw "Task $id was not found."
            }
            Write-TaskStore -Path $dataFile -Tasks $remaining
            $summary = [pscustomobject]@{ removedId = $id }
            if ($asJson) {
                Write-TaskForgeOutput -Value $summary -AsJson $true
            }
            else {
                "Removed task $id."
            }
        }
        'config' {
            if (-not $configAction) {
                throw 'config requires an action: set, get, or list.'
            }
            switch ($configAction) {
                'set' {
                    Assert-KnownOptions -Options $options -Allowed @('key', 'value', 'config-file')
                    $key = Get-RequiredOption -Options $options -Name 'key'
                    if ($key -notin (Get-TaskForgeConfigKeys)) {
                        throw "Unknown config key: $key"
                    }
                    $rawValue = Get-RequiredOption -Options $options -Name 'value'
                    $storeValue = if ($key -eq 'defaultJson') {
                        ConvertTo-TaskForgeBoolean -Value $rawValue
                    }
                    else {
                        $rawValue
                    }
                    $config[$key] = $storeValue
                    Write-TaskForgeConfig -Path $configFile -Config $config
                    "Set $key = $storeValue"
                }
                'get' {
                    Assert-KnownOptions -Options $options -Allowed @('key', 'config-file', 'json')
                    $key = Get-RequiredOption -Options $options -Name 'key'
                    if ($key -notin (Get-TaskForgeConfigKeys)) {
                        throw "Unknown config key: $key"
                    }
                    $value = if ($config.Contains($key)) { $config[$key] } else { $null }
                    if ($asJson) {
                        Write-TaskForgeOutput -Value ([pscustomobject]@{ key = $key; value = $value }) -AsJson $true
                    }
                    else {
                        [string]$value
                    }
                }
                'list' {
                    Assert-KnownOptions -Options $options -Allowed @('config-file', 'json')
                    if ($asJson) {
                        $obj = [ordered]@{}
                        foreach ($k in Get-TaskForgeConfigKeys) {
                            if ($config.Contains($k)) { $obj[$k] = $config[$k] }
                        }
                        Write-TaskForgeOutput -Value ([pscustomobject]$obj) -AsJson $true
                    }
                    else {
                        $lines = [System.Collections.Generic.List[string]]::new()
                        $banner = Get-TaskForgeBanner
                        if (-not [string]::IsNullOrEmpty($banner)) {
                            $lines.Add($banner)
                        }
                        foreach ($k in Get-TaskForgeConfigKeys) {
                            if ($config.Contains($k)) {
                                $lines.Add(("{0} = {1}" -f $k, $config[$k]))
                            }
                        }
                        if ($lines.Count -eq 0) {
                            'No configuration.'
                        }
                        else {
                            $lines -join "`n"
                        }
                    }
                }
                default {
                    throw "Unknown config action: $configAction"
                }
            }
        }
        'help' {
            Assert-KnownOptions -Options $options -Allowed @()
            @'
TaskForge
  add --title TEXT [--description TEXT] [--data-file PATH] [--json] [--config-file PATH]
  list [--data-file PATH] [--json] [--config-file PATH]
  complete --id ID [--data-file PATH] [--json] [--config-file PATH]
  remove --id ID [--data-file PATH] [--json] [--config-file PATH]
  config set --key KEY --value VALUE [--config-file PATH]
  config get --key KEY [--json] [--config-file PATH]
  config list [--json] [--config-file PATH]
'@
        }
        default {
            throw "Unknown command: $Command"
        }
    }
}
catch {
    [Console]::Error.WriteLine("TaskForge: $($_.Exception.Message)")
    exit 1
}
